// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.deal(address(this), amount);
        // fund the contract
        vm.prank(address(this));
        (bool okPay,) = payable(address(c)).call{value: amount}("");
        assertTrue(okPay);
        uint256 before = address(c).balance;
        assertTrue(before == amount);

        // owner (deployer = this test contract) triggers suicide
        vm.prank(address(this));
        c.sudicideAnyone();

        // General rule: after the owner calls sudicideAnyone, C's balance is drained to 0.
        // The mutant (no selfdestruct) keeps the balance, violating this for any amount > 0.
        assertTrue(address(c).balance == 0, "contract must self-destruct and drain balance");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);

        // caller funds the contract
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);
        assertEq(address(c).balance, amount);

        // contract constructor sets __owner = deployer (this test contract)
        vm.prank(address(this));
        c.sudicideAnyone();

        // RULE: the suicide beneficiary is the caller of the funding sender's funds —
        // actually the beneficiary is msg.sender of sudicideAnyone; the caller (owner)
        // receives the contract's balance. Here owner == this test contract, so the
        // contract must be emptied and the owner credited.
        assertTrue(address(c).balance == 0 && address(this).balance == amount);
    }
}

