// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address filler) public {
        vm.assume(filler != address(0));
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        // The owner of C is this test contract (msg.sender of setUp).
        address owner = address(this);
        // Give the fuzzer-controlled filler some ether so the domain is wide.
        vm.deal(filler, 1 ether);
        // Fund the contract under test with the fuzzed amount.
        vm.deal(address(c), amount);
        // Adversarially drain any stray balance so the delta is exactly `amount`.
        uint256 ownerBefore = owner.balance - address(c).balance;
        // Owner calls the entry point; beneficiary must be msg.sender.
        c.sudicideAnyone();
        // Reference: owner receives the whole contract balance (delta == amount).
        // Mutant: funds go to address(0), owner balance unchanged -> breaks for some input.
        assertTrue(owner.balance == ownerBefore + amount);
    }
}

