    function test(bool dummy) external {
        dummy; // silence unused warning
        bool reverted = false;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}

