contract InvMutTest {
    C c;
    constructor(C _c) { require(address(_c).code.length > 0); c = _c; }

    function test(address beneficiary) external {
        // The destroy beneficiary must be an external address, not this test
        // contract itself (which would keep the privileged self-address state
        // alive across the destruction).
        require(beneficiary != address(this));
        // Setup: destroy c so that it holds no exploitable privileged state
        // for this contract; afterwards every external call into c reverts.
        c.sudicideAnyone();
        bool reverted = false;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }

